INSERT INTO `programs` (`id`, `code`, `title`, `short_title`, `category`, `department`, `description`, `duration`, `units`, `image_path`, `prospectus_path`, `enrolled_students`, `status`, `highlights`, `career_opportunities`, `admission_requirements`, `program_head_name`, `teachers`, `created_at`, `updated_at`, `program_head_id`) VALUES
(1, 'BSIS', 'Bachelor of Science in Information Systems', 'BS Information Systems', '4-years', 'BSIS', 'A comprehensive program focusing on information systems analysis, design, and implementation for modern business environments.', '4 Years', '150 Units', 'assets/img/programs/bsis.jpg', '../../assets/img/programs/prospectus/BSIS-prospectus-1773880533.xlsx', 151, 'active', '[\"Hands-on training in systems analysis and design\",\"Industry-aligned curriculum with IT certifications\",\"Capstone project with real-world business clients\",\"Exposure to enterprise software and cloud platforms\",\"Strong focus on database management and web development\",\"On-the-Job Training (OJT) in leading IT companies\"]', '[\"Systems Analyst\",\"Database Administrator\",\"IT Project Manager\",\"Web Developer \\/ Full-Stack Developer\",\"Business Intelligence Analyst\",\"Network Administrator\",\"Software Quality Assurance Engineer\",\"IT Consultant\"]', '[\"Original and photocopy of Grade 12 Report Card (Form 138)\",\"PSA-authenticated Birth Certificate\",\"Certificate of Good Moral Character from previous school\",\"Two (2) 2x2 ID photos with white background\",\"Accomplished Admission Application Form\",\"Entrance examination and interview\"]', 'JUNE PAUL ANONUEVO', '[]', '2026-01-29 14:47:27', '2026-05-12 12:09:35', NULL),
(2, 'BPA', 'Bachelor of Public Administration', 'BS Public Administration', '4-years', 'BPA', 'Program designed to develop competent public administrators and managers for government service and public sector organizations.', '4 Years', '140 Units', 'assets/img/programs/BPA-1769735549.jpg', '../../assets/prospectus/BPA-and-BSIS-PROSPECTUS.xlsx', 142, 'active', '[\"Comprehensive study of public governance and administration\",\"Exposure to local government units and national agencies\",\"Training in public policy analysis and formulation\",\"Community development and extension service programs\",\"Internship in government offices and NGOs\",\"Strong foundation in law, ethics, and public service\"]', '[\"Local Government Officer\",\"Public Administrator \\/ Civil Servant\",\"Policy Analyst\",\"Community Development Officer\",\"NGO Program Coordinator\",\"Government Liaison Officer\",\"Administrative Officer (National Agencies)\",\"Barangay \\/ Municipal Official\"]', '[\"Original and photocopy of Grade 12 Report Card (Form 138)\",\"PSA-authenticated Birth Certificate\",\"Certificate of Good Moral Character from previous school\",\"Two (2) 2x2 ID photos with white background\",\"Accomplished Admission Application Form\",\"Entrance examination and interview\"]', 'CEDRICK H. ALMAREZ', '[]', '2026-01-29 14:47:27', '2026-05-12 12:09:35', NULL),
(3, 'BTVTED-WFT', 'BTVTED-Welding and Fabrication Technology', 'Welding Fabrication Technology', '4-years', 'WFT', 'Hands-on program providing comprehensive training in various welding techniques and fabrication processes for industrial applications.', '4 Years', '80 Units', '../../assets/img/programs/BTVTED-WFT-1773903558.jpg', '../../assets/img/programs/prospectus/BTVTED-WFT-prospectus-1772174817.xlsx', 119, 'active', '[\"TESDA NC II\\/III certification in Welding and Fabrication\",\"State-of-the-art welding laboratory and equipment\",\"Training in SMAW, GMAW, GTAW, and FCAW welding processes\",\"Dual competency in technical education and industrial skills\",\"Practicum in manufacturing and construction companies\",\"Prepares graduates for both teaching and industry careers\"]', '[\"Welding Inspector \\/ Supervisor\",\"Technical-Vocational Teacher (DepEd)\",\"Metal Fabrication Technician\",\"Industrial Welder (local and overseas)\",\"Structural Steel Fabricator\",\"Welding Trainer \\/ Instructor\",\"Quality Control Inspector\"]', '[\"Original and photocopy of Grade 12 Report Card (Form 138)\",\"PSA-authenticated Birth Certificate\",\"Certificate of Good Moral Character from previous school\",\"Two (2) 2x2 ID photos with white background\",\"Accomplished Admission Application Form\",\"Entrance examination and interview\",\"Medical certificate (for physical fitness)\"]', 'PAMELA FAYE D. GELENA', '[]', '2026-01-29 14:47:27', '2026-05-12 12:09:35', NULL),
(5, 'BTVTED-CHS', 'BTVTED-Computer Hardware Servicing', 'Computer Hardware Servicing', '4-years', 'BTVTED', 'Focuses on installing, maintaining, troubleshooting, and repairing computer systems and networks; while also training students in teaching methods so they can pass on these skills in schools or training centers.', '4 Years', '150 Units', '../../assets/img/programs/BTVTED-CHS-1773903522.jpg', '../../assets/img/programs/prospectus/BTVTED-CHS-prospectus-1772174799.xlsx', 128, 'active', '[\"TESDA NC II certification in Computer Hardware Servicing\",\"Dual training in technical education and hardware technology\",\"Hands-on laboratory work with actual computer systems\",\"Training in network installation and administration\",\"Prepares graduates for both teaching and industry careers\",\"Practicum in schools and technical-vocational institutions\"]', '[\"Computer Hardware Technician\",\"Technical-Vocational Teacher (DepEd)\",\"Network Administrator\",\"IT Support Specialist\",\"Computer Laboratory Technician\",\"Electronics Technician\",\"Technical Trainer \\/ Instructor\"]', '[\"Original and photocopy of Grade 12 Report Card (Form 138)\",\"PSA-authenticated Birth Certificate\",\"Certificate of Good Moral Character from previous school\",\"Two (2) 2x2 ID photos with white background\",\"Accomplished Admission Application Form\",\"Entrance examination and interview\"]', 'PAMELA FAYE D. GELENA', '[]', '2026-02-27 06:46:39', '2026-05-12 12:09:35', NULL);
